W_NSA = W_NS


# ------------------------------------------------------------------------------------------ 共通の部品（このファイルの中だけで使う）
_MK = re.compile(r'\{([^{}]*)\}')


def mk(s):
    """文中の印を run の並びにする：{旧>新}＝削除して挿入、{+挿入}、{-削除}、{_下線}。印のない所はそのまま"""
    runs = []; pos = 0
    for m in _MK.finditer(s):
        if m.start() > pos: runs.append(('', s[pos:m.start()]))
        b = m.group(1)
        if b.startswith('+'): runs.append(('ins', b[1:]))
        elif b.startswith('-'): runs.append(('del', b[1:]))
        elif b.startswith('_'): runs.append(('u', b[1:]))
        else:
            o, n = b.split('>', 1)
            if o: runs.append(('del', o))
            if n: runs.append(('ins', n))
        pos = m.end()
    if pos < len(s): runs.append(('', s[pos:]))
    return runs


def plain(s, mode):
    """印つきの文を、履歴をすべて承諾（'acc'）／すべて元に戻す（'rej'）したあとの文にする"""
    keep = ('', 'u', 'ins', 'mt') if mode == 'acc' else ('', 'u', 'del', 'mf')
    return ''.join(t for k, t in mk(s) if k in keep)


def resolve(blocks, mode):
    """変更履歴つきの blocks から、承諾後（'acc'）または変更前（'rej'）の blocks を作る"""
    out = []
    for b in blocks:
        if isinstance(b, str): out.append(plain(b, mode))
        elif b[0] == 'cmt': out += resolve([b[1]], mode)
        elif b[0] in ('ins', 'mt'):
            if mode == 'acc': out.append(plain(b[1], 'acc'))
        elif b[0] in ('del', 'mf'):
            if mode == 'rej': out.append(''.join(t for k, t in mk(b[1])))
        elif b[0] == 'table':
            rows = []
            for r in b[1]:
                if isinstance(r, tuple):
                    if (r[0] == 'ins') == (mode == 'acc'): rows.append([''.join(t for k, t in mk(str(c))) for c in r[1]])
                else: rows.append([plain(str(c), mode) for c in r])
            out.append(('table', rows) + tuple(b[2:]))
    return out


def count_trk(blocks):
    """変更履歴の数：(文中の挿入, 文中の削除, 段落ごとの挿入, 段落ごとの削除, 移動した段落, 表の行の挿入)"""
    c = dict(ins=0, dele=0, pins=0, pdel=0, mv=0, rins=0)
    for b in blocks:
        if isinstance(b, tuple) and b[0] == 'cmt': b = b[1]
        if isinstance(b, str):
            for k, t in mk(b): c['ins'] += k == 'ins'; c['dele'] += k == 'del'
        elif b[0] == 'ins': c['pins'] += 1
        elif b[0] == 'del': c['pdel'] += 1
        elif b[0] == 'mt':
            c['mv'] += 1
            for k, t in mk(b[1]): c['ins'] += k == 'ins'
        elif b[0] == 'table':
            for r in b[1]:
                if isinstance(r, tuple): c['rins'] += 1
                else:
                    for v in r:
                        for k, t in mk(str(v)): c['ins'] += k == 'ins'; c['dele'] += k == 'del'
    return c


def wdoc(path, title, blocks, header=None, footer='page', author='先方 法務部', date='2026-11-18T10:24:00Z', size=10.5, wide=False):
    """Word 文書（rdocx を広げたもの）。blocks の要素：
       文字列（段落。'## ' で見出し、'---pb---' で改ページ。文中に mk() の印があれば変更履歴・下線になる）
       ('ins', 文)／('del', 文)＝段落ごとの挿入・削除（段落記号にも履歴が付く）
       ('mf', 文, 名前, 位置)／('mt', 文, 名前, 位置)＝段落の移動（Word の「移動」の履歴。位置は 'first'・'mid'・'last'）
       ('table', rows[, 幅mmのリスト])＝表。行を ('ins', セルのリスト) にすると、行の挿入の履歴。セルの中の '\n' は段落の区切り
       ('cmt', 文, コメント, 書いた人, イニシャル)＝コメント付きの段落"""
    d = docx.Document()
    st = d.styles['Normal']; st.font.name = 'Yu Mincho'; st.font.size = Pt(size)
    st.element.rPr.rFonts.set(qn('w:eastAsia'), 'Noto Serif CJK JP')
    sec = d.sections[0]
    sec.page_width, sec.page_height = (Mm(297), Mm(210)) if wide else (Mm(210), Mm(297))
    if wide: sec.orientation = 1; sec.left_margin = sec.right_margin = Mm(18); sec.top_margin = sec.bottom_margin = Mm(18)
    if header: sec.header.paragraphs[0].text = header
    if footer == 'page':
        p = sec.footer.paragraphs[0]; p.alignment = 1
        p.add_run('- '); p._p.append(_R3._fld('PAGE', '1')); p._p.append(parse_xml(f'<w:r {W_NS}><w:t xml:space="preserve"> / </w:t></w:r>'))
        p._p.append(_R3._fld('NUMPAGES', '1')); p._p.append(parse_xml(f'<w:r {W_NS}><w:t xml:space="preserve"> -</w:t></w:r>'))
    elif footer: sec.footer.paragraphs[0].text = footer
    if title: d.add_heading(title, 1)
    UL = '<w:rPr><w:u w:val="single"/></w:rPr>'
    ids = itertools.count(100); TAG = {'ins': 'w:ins', 'del': 'w:del', 'mf': 'w:moveFrom', 'mt': 'w:moveTo'}; att = f'w:author="{esc(author)}" w:date="{date}"'; rng = {}

    def rx(kind, t):
        if kind in ('', 'u'):
            return f'<w:r {W_NS}>{UL if kind == "u" else ""}<w:t xml:space="preserve">{esc(t)}</w:t></w:r>'
        tt = 'w:delText' if kind == 'del' else 'w:t'
        return f'<{TAG[kind]} {W_NS} w:id="{next(ids)}" {att}><w:r><{tt} xml:space="preserve">{esc(t)}</{tt}></w:r></{TAG[kind]}>'

    def mark(p, kind):   # 段落記号そのものの履歴
        p._p.get_or_add_pPr().append(parse_xml(f'<w:rPr {W_NS}><{TAG[kind]} w:id="{next(ids)}" {att}/></w:rPr>'))

    def fill(p, runs, kind=None):
        if kind in ('ins', 'del', 'mf'): runs = [(kind, t) for k, t in runs]
        elif kind == 'mt': runs = [(k if k == 'ins' else 'mt', t) for k, t in runs]
        for k, t in runs:
            if t: p._p.append(parse_xml(rx(k, t)))

    pb = [False]

    def newp(s):   # 段落を作る（見出しなら「見出し2」）。直前が改ページの印なら「段落前で改ページ」にする（空のページができない）
        p = d.add_heading('', 2) if s.startswith('## ') else d.add_paragraph()
        if pb[0]: p.paragraph_format.page_break_before = True; pb[0] = False
        return p, (s[3:] if s.startswith('## ') else s)

    def para(s, kind=None, mv=None):
        p, s = newp(s)
        if kind: mark(p, kind)
        if mv and mv[1] == 'first':
            rng[(kind, mv[0])] = next(ids)
            p._p.append(parse_xml(f'<w:move{"From" if kind == "mf" else "To"}RangeStart {W_NS} w:id="{rng[(kind, mv[0])]}" {att} w:name="{mv[0]}"/>'))
        fill(p, mk(s), kind)
        if mv and mv[1] == 'last': p._p.append(parse_xml(f'<w:move{"From" if kind == "mf" else "To"}RangeEnd {W_NS} w:id="{rng[(kind, mv[0])]}"/>'))
        return p

    for b in blocks:
        if isinstance(b, str):
            if b == '---pb---': pb[0] = True
            else: para(b)
        elif b[0] in ('ins', 'del'): para(b[1], b[0])
        elif b[0] in ('mf', 'mt'): para(b[1], b[0], (b[2], b[3]))
        elif b[0] == 'cmt':
            p = para(b[1]); rs = [docx.text.run.Run(r, p) for r in p._p.findall(qn('w:r'))] or [docx.text.run.Run(r, p) for r in p._p.iter(qn('w:r'))]
            c = d.add_comment(runs=[rs[0], rs[-1]], text=b[2], author=b[3], initials=b[4])
            c._comment_elm.date = datetime.datetime.strptime(date, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc)
        elif b[0] == 'table':
            rows = b[1]; ncol = max(len(r[1]) if isinstance(r, tuple) else len(r) for r in rows)
            t = d.add_table(rows=len(rows), cols=ncol); t.style = 'Table Grid'
            for i, r in enumerate(rows):
                rk = None
                if isinstance(r, tuple): rk, r = r
                if rk: t.rows[i]._tr.get_or_add_trPr().append(parse_xml(f'<{TAG[rk]} {W_NS} w:id="{next(ids)}" {att}/>'))
                for j, v in enumerate(r):
                    cell = t.cell(i, j)
                    for n, part in enumerate(str(v).split('\n')):
                        p = cell.paragraphs[0] if n == 0 else cell.add_paragraph()
                        if rk: mark(p, rk)
                        fill(p, mk(part), rk)
            if len(b) > 2 and b[2]:
                t.autofit = False
                for j, w in enumerate(b[2]): t.columns[j].width = Mm(w)
                for r in t.rows:
                    for j, w in enumerate(b[2]): r.cells[j].width = Mm(w)
            d.add_paragraph('')
    d.save(P(path))


def pdf_words(pdf):
    """PDF の語の位置（ページ番号（1始まり）, 文字, x0, y0, x1, y1）。単位は pt、左上が原点"""
    out = subprocess.run(['pdftotext', '-bbox', pdf, '-'], capture_output=True, text=True, check=True).stdout
    res = []; pg = 0
    for line in out.split('\n'):
        if '<page ' in line: pg += 1
        m = re.search(r'<word xMin="([\d.\-]+)" yMin="([\d.\-]+)" xMax="([\d.\-]+)" yMax="([\d.\-]+)">(.*)</word>', line)
        if m: res.append((pg, m.group(5).replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>').replace('&quot;', '"'), float(m.group(1)), float(m.group(2)), float(m.group(3)), float(m.group(4))))
    return res


def pdf_text(pdf):
    return subprocess.run(['pdftotext', '-layout', pdf, '-'], capture_output=True, text=True, check=True).stdout


def sub_box(w, sub, k):
    """語 w（pdf_words の要素）の中の文字列 sub の位置（画素。k は pt→画素の倍率）。全角を1、半角を0.5 の幅として割り振る"""
    pg, s, x0, y0, x1, y1 = w; wd = lambda t: sum(0.5 if ord(c) < 0x2000 else 1 for c in t); i = s.index(sub); u = (x1 - x0) / wd(s)
    return ((x0 + u * wd(s[:i])) * k, y0 * k, (x0 + u * wd(s[:i + len(sub)])) * k, y1 * k)


def strike(im, box, color=(205, 30, 30)):
    """手書きの訂正の二重線（box は画素の x0, y0, x1, y1）"""
    d = ImageDraw.Draw(im); x0, y0, x1, y1 = box; ym = (y0 + y1) / 2
    d.line([x0 - 4, ym - 4, x1 + 4, ym - 6], fill=color, width=3); d.line([x0 - 4, ym + 4, x1 + 4, ym + 2], fill=color, width=3)


def seeded(seed, f):
    """部品の scan_look は全体の乱数を使うので、種を決めてから呼び、終わったら元に戻す（作り直しても同じ絵になる）"""
    def g():
        st = random.getstate(); random.seed(seed)
        try: f()
        finally: random.setstate(st)
    return g


