    def nda(order, v):
        sub = {'D1': '14', 'D2': '30', 'D3': '', 'D4': '1', 'D5': '3', 'D6': '東京'} if v == 0 else {'D1': '30', 'D2': '14', 'D3': '（合理的な弁護士費用を含む。）', 'D4': '2', 'D5': '5', 'D6': '東京'}
        sub['R1'] = str(order.index('秘密保持義務') + 1); sub['R2'] = str(order.index('損害賠償' if v else '知的財産権') + 1)
        out = ['＿＿＿＿＿＿＿＿（以下「甲」という。）と株式会社リンクウェイブ（以下「乙」という。）は、次のとおり秘密保持契約（以下「本契約」という。）を締結する。']
        for i, t in enumerate(order):
            out.append(f'## 第{i + 1}条（{t}）')
            for p in N[t]:
                for k, val in sub.items(): p = p.replace('{' + k + '}', val)
                if v: p = p.replace('または', '又は').replace('および', '及び').replace('もしくは', '若しくは')
                out.append(p)
        out += ['本契約の成立を証するため、本書2通を作成し、甲乙記名押印のうえ、各1通を保有する。' if v == 0 else '本契約の成立を証するため、本書の電磁的記録を作成し、甲乙が電子署名を施したうえ、各自その電磁的記録を保管する。',
                '20　　年　　月　　日', '甲', '乙　東京都千代田区神田錦町四丁目7番2号　株式会社リンクウェイブ']
        return out
