    m2 = 'mL/min/1.73m' + sup('2')
    tb = lambda rows, cls='': f'<table class="{cls}">' + ''.join('<tr>' + ''.join(f'<{"th" if i == 0 else "td"}>{c}</{"th" if i == 0 else "td"}>' for c in r) + '</tr>' for i, r in enumerate(rows)) + '</table>'
    H = []
