def buhinzu(path, rev):
    """ブラケット BRK-4410-21 の部品図。rev は 'C' か 'D'"""
    v = rev == 'D'; c = rl_canvas.Canvas(P(path), pagesize=landscape(A3)); W, H = landscape(A3)
    hd = 12.5 if v else 12.0; tol = '±0.02' if v else '±0.05'; sy = 45.5 if v else 45.0; nx = 68.0 if v else 70.0   # 取付穴の径／ピッチの公差／長穴の高さ／切欠きの左端
    def T(x, y, s, sz=8, rot=0, center=False):
        c.saveState(); c.translate(x, y); c.rotate(rot); c.setFont('IPAG', sz)
        (c.drawCentredString if center else c.drawString)(0, 0, s); c.restoreState()
    def arrow(x, y, dx, dy):
        p = c.beginPath(); p.moveTo(x, y); p.lineTo(x - 7 * dx + 2.2 * dy, y - 7 * dy + 2.2 * dx); p.lineTo(x - 7 * dx - 2.2 * dy, y - 7 * dy - 2.2 * dx); p.close(); c.drawPath(p, fill=1)
    def hdim(x1, x2, y0, yd, s):
        c.setLineWidth(0.35); c.line(x1, y0, x1, yd - 4 if yd < y0 else yd + 4); c.line(x2, y0, x2, yd - 4 if yd < y0 else yd + 4); c.line(x1, yd, x2, yd); arrow(x1, yd, -1, 0); arrow(x2, yd, 1, 0); T((x1 + x2) / 2, yd + 3, s, 8, center=True)
    def vdim(y1, y2, x0, xd, s):
        c.setLineWidth(0.35); c.line(x0, y1, xd - 4 if xd < x0 else xd + 4, y1); c.line(x0, y2, xd - 4 if xd < x0 else xd + 4, y2); c.line(xd, y1, xd, y2); arrow(xd, y1, 0, -1); arrow(xd, y2, 0, 1); T(xd - 3, (y1 + y2) / 2, s, 8, rot=90, center=True)
    def center(x, y, r):
        c.setLineWidth(0.3); c.setDash([8, 2, 2, 2]); c.line(x - r - 6, y, x + r + 6, y); c.line(x, y - r - 6, x, y + r + 6); c.setDash()
    def leader(x, y, tx, ty, s):
        c.setLineWidth(0.35); c.line(x, y, tx, ty); c.line(tx, ty, tx + c.stringWidth(s, 'IPAG', 8) + 4, ty); T(tx + 2, ty + 3, s, 8)
    def fcf(x, y, sym, cells):   # 幾何公差の枠
        c.setLineWidth(0.5); w = [20] + [max(22, c.stringWidth(s, 'IPAG', 8) + 8) for s in cells]; xx = x
        for i, wi in enumerate(w):
            c.rect(xx, y, wi, 15)
            if i: T(xx + wi / 2, y + 4, cells[i - 1], 8, center=True)
            xx += wi
        cx, cy = x + 10, y + 7.5
        if sym == 'perp': c.line(cx - 5, cy - 4, cx + 5, cy - 4); c.line(cx, cy - 4, cx, cy + 5)
        elif sym == 'pos': c.circle(cx, cy, 4); c.line(cx - 6, cy, cx + 6, cy); c.line(cx, cy - 6, cx, cy + 6)
        elif sym == 'flat': p = c.beginPath(); p.moveTo(cx - 6, cy - 3); p.lineTo(cx + 3, cy - 3); p.lineTo(cx + 6, cy + 3); p.lineTo(cx - 3, cy + 3); p.close(); c.drawPath(p)
    def datum(x, y, s):
        c.setLineWidth(0.5); p = c.beginPath(); p.moveTo(x - 5, y); p.lineTo(x + 5, y); p.lineTo(x, y - 7); p.close(); c.drawPath(p, fill=1); c.line(x, y - 7, x, y - 16); c.rect(x - 7, y - 30, 14, 14); T(x, y - 27, s, 9, center=True)
    def frame(sheet, title):
        c.setLineWidth(1.4); c.rect(24, 24, W - 48, H - 48); c.setLineWidth(0.7); x0 = W - 24 - 360; c.rect(x0, 24, 360, 100)
        for k in (1, 2, 3): c.line(x0, 24 + k * 25, W - 24, 24 + k * 25)
        c.line(x0 + 200, 49, x0 + 200, 124)
        T(x0 + 6, 106, 'ブラケット，センサ取付', 11); T(x0 + 206, 106, f'図番 BRK-4410-21', 10); T(x0 + 6, 81, f'名称 {title}', 9); T(x0 + 206, 81, f'Rev. {rev}　　シート {sheet}/2', 10)
