            line('寸法', a, y0, a, yd); line('寸法', b, y0, b, yd); line('寸法', a, yd, b, yd); ent('TEXT', '寸法', (10, (a + b) / 2.0), (20, yd + 1.0), (30, 0.0), (40, 3.5), (1, s))
