        for i in range(40): line('図枠', -40 + i * 10.5, -60, -40 + i * 10.5, -57); line('図枠', -40 + i * 10.5, 200, -40 + i * 10.5, 197)   # 図枠の目盛
        for (a, b), s in [((262, -40), 'ブラケット，センサ取付'), ((322, -40), 'BRK-4410-21'), ((262, -55), '三峰精機工業株式会社'), ((322, -55), 'REV D  2026/11/20' if v else 'REV C  2025/09/18')]: ent('TEXT', '図枠', (10, float(a)), (20, float(b)), (30, 0.0), (40, 3.5), (1, s))
