def r04(d):
    rnd = random.Random(404)
    q = lambda v: '"' + str(v).replace('"', '""') + '"' if any(c in str(v) for c in ',"') else str(v)
    brands = ['ﾐﾅﾄ', '北星', 'ｻﾝﾙｰﾌ', '和泉屋', 'ｸﾞﾘｰﾝﾋﾙ', '東雲', 'ﾏﾙｶﾜ', 'あおば', 'ｷﾀﾉ', '日乃出']
    cats = [('BV', 9000, [('緑茶 ﾍﾟｯﾄﾎﾞﾄﾙ', '500ml×24', 24), ('ﾐﾈﾗﾙｳｫｰﾀｰ', '2L×6', 6), ('炭酸水 ﾚﾓﾝ', '500ml×24', 24), ('麦茶 ﾃｨｰﾊﾞｯｸﾞ', '54袋×12', 12), ('ｺｰﾋｰ 微糖 缶', '185g×30', 30), ('野菜ｼﾞｭｰｽ 紙ﾊﾟｯｸ', '200ml×24', 24)]),
            ('DG', 7000, [('洗濯用洗剤 詰替', '810g×15', 15), ('台所用洗剤 ｵﾚﾝｼﾞ', '240ml×20', 20), ('ﾊﾝﾄﾞｿｰﾌﾟ 泡ﾀｲﾌﾟ', '250ml×24', 24), ('柔軟剤 ﾌﾛｰﾗﾙ', '540ml×12', 12), ('漂白剤 ｷｯﾁﾝ用', '600ml×12', 12)]),
            ('FD', 14000, [('ｶｯﾌﾟ麺 しょうゆ', '77g×20', 20), ('ﾚﾄﾙﾄｶﾚｰ 中辛', '180g×30', 30), ('ﾊﾟｽﾀ 1.6mm', '500g×20', 20), ('ﾂﾅ缶 ｵｲﾙ漬', '70g×48', 48), ('ﾎﾟﾃﾄﾁｯﾌﾟｽ うすしお', '60g×12', 12), ('ﾋﾞｽｹｯﾄ ﾊﾞﾀｰ', '18枚×24', 24), ('味噌 赤だし', '750g×8', 8), ('ｹﾁｬｯﾌﾟ ﾁｭｰﾌﾞ', '500g×20', 20)]),
            ('HK', 9000, [('ｷｯﾁﾝﾍﾟｰﾊﾟｰ 2ﾛｰﾙ', '2ﾛｰﾙ×24', 24), ('ﾃｨｯｼｭ 5箱ﾊﾟｯｸ', '5箱×12', 12), ('ﾄｲﾚｯﾄﾍﾟｰﾊﾟｰ ﾀﾞﾌﾞﾙ', '12ﾛｰﾙ×8', 8), ('ﾗｯﾌﾟ 30cm×50m', '1本×30', 30), ('ｺﾞﾐ袋 45L', '50枚×20', 20), ('ｱﾙﾐﾎｲﾙ 25cm×8m', '1本×60', 60)]),
            ('PT', 5000, [('ﾄﾞｯｸﾞﾌｰﾄﾞ 成犬用', '2.7kg×4', 4), ('ｷｬｯﾄﾌｰﾄﾞ ﾏｸﾞﾛ', '70g×48', 48), ('猫砂 ひのき', '7L×6', 6), ('ﾍﾟｯﾄｼｰﾂ ﾚｷﾞｭﾗｰ', '100枚×4', 4)]),
            ('ST', 6000, [('ﾎﾞｰﾙﾍﾟﾝ 黒 0.5', '10本×20', 20), ('ｺﾋﾟｰ用紙 A4', '500枚×5', 5), ('ﾉｰﾄ B5 5冊', '5冊×10', 10), ('付箋 75×75', '10個×24', 24), ('ｸﾘｱﾌｧｲﾙ A4', '100枚×10', 10)])]
    memo = ['', '', '', '', '', '要冷蔵', '要冷蔵,天地無用', 'ﾜﾚﾓﾉ注意', '販売終了予定', '"特売"対象', '直射日光を避ける,高温注意', 'ｹｰｽ単位出荷のみ']
    def jan(r):
        b = r.choice(['49', '49', '49', '49', '49', '49', '49', '45', '45', '00']) + ''.join(r.choice('0123456789') for _ in range(10))
        cd = (10 - (sum(int(c) for c in b[0::2]) + 3 * sum(int(c) for c in b[1::2])) % 10) % 10; return b + str(cd)
    def row(code, cat, items, r, day):
        nm, spec, per = r.choice(items); food = cat in ('BV', 'FD', 'PT')
        return [code, jan(r), f'{r.choice(brands)} {nm}', spec, str(per), str(r.choice([0, 12, 60, 240, 480]) + r.randrange(0, 2600)), (f'{r.randrange(80, 6000)}' if r.random() < 0.6 else f'{r.randrange(8000, 600000) / 100:.2f}'), f'{r.choice("ABCDEFGH")}-{r.randrange(1, 41):02d}-{r.randrange(1, 9):02d}',
                f'L26{r.randrange(1, 11):02d}{r.choice("ABCD")}{r.randrange(1, 100):02d}', (f'2027/{r.randrange(1, 13):02d}/{r.randrange(1, 29):02d}' if food else ''), f'2026/{day}', r.choice(memo)]
    base = []; catof = {}
    for cat, n, items in cats:
        num = 100000
        for _ in range(n): num += rnd.choice([1, 1, 2, 3]); base.append(row(f'{cat}-{num}', cat, items, rnd, f'10/{rnd.randrange(1, 32):02d}')); catof[base[-1][0]] = (cat, items)
    assert len(base) == 50000 and len({r[0] for r in base}) == 50000 and [r[0] for r in base] == sorted(r[0] for r in base)
    HDR = ['商品コード', 'JANコード', '品名', '規格', '入数', '在庫数', '単価', '棚番', 'ロット', '賞味期限', '更新日', '備考']
    B0, BN = 31000, 400   # 並び順が変わるかたまり（前月の 0始まりの位置）
    free = [i for i in range(50000) if not (B0 - 2 <= i < B0 + BN + 2)]
    big = [i for i in free if int(base[i][5]) >= 1000]; v1 = rnd.sample(big, 15)                                   # "1,200" の形にする行
    rest = [i for i in free if i not in set(v1)]; pick = rnd.sample(rest, 200 + 20 + 10 + 10)
    food = [i for i in pick if base[i][9]]; c_exp = food[:15]; others = [i for i in pick if i not in set(c_exp)]
    c_qty, c_prc, c_loc, dele, v2, v3 = others[:120], others[120:160], others[160:185], others[185:205], others[205:215], others[215:225]
    new = {i: list(base[i]) for i in range(50000)}; ex = {}
    for i in c_qty: o = int(base[i][5]); n_ = max(0, o + rnd.choice([-1, 1]) * rnd.randrange(1, 400)); n_ = n_ if n_ != o else o + 24; new[i][5] = str(n_); ex[i] = ('在庫数', base[i][5], str(n_))
    for i in c_prc: o = base[i][6]; n_ = (f'{float(o) * 1.05:.2f}' if '.' in o else str(int(o) + rnd.randrange(2, 60))); new[i][6] = n_; ex[i] = ('単価', o, n_)
    for i in c_loc:
        while True:
            n_ = f'{rnd.choice("ABCDEFGH")}-{rnd.randrange(1, 41):02d}-{rnd.randrange(1, 9):02d}'
            if n_ != base[i][7]: break
        new[i][7] = n_; ex[i] = ('棚番', base[i][7], n_)
    for i in c_exp: n_ = f'2028/{base[i][9][5:]}'; new[i][9] = n_; new[i][8] = 'L2611' + base[i][8][5:]; ex[i] = ('賞味期限とロット', base[i][9] + '・' + base[i][8], n_ + '・' + new[i][8])
    for i in c_qty + c_prc + c_loc + c_exp: new[i][10] = f'2026/11/{rnd.randrange(1, 29):02d}'
    for i in v2: new[i][2] = base[i][2] + ' '                      # 品名の末尾に半角の空白
    for i in v3: new[i][2] = base[i][2].replace(' ', '　', 1)    # 品名の1つ目の半角の空白を全角の空白に
    assert all(' ' in base[i][2] for i in v3)
    fmt = lambda r, comma=False: ','.join(q(f'{int(v):,}') if (comma and k == 5) else q(v) for k, v in enumerate(r))
    codes = {r[0] for r in base}; adds = []   # 追加する 24行（コードの順の位置へ）＋末尾に 6行
    while len(adds) < 24:
        i = rnd.choice(free[:-1]); pre, num = base[i][0].split('-'); c = f'{pre}-{int(num) + 1}'
        if c not in codes and i not in dele and i + 1 not in dele and all(a[0] != i for a in adds) and base[i + 1][0][:2] == pre: codes.add(c); adds.append((i, row(c, pre, catof[base[i][0]][1], rnd, f'11/{rnd.randrange(1, 29):02d}')))
    tail = [row(f'ST-{int(base[-1][0][3:]) + 5 + k * 2}', 'ST', cats[5][2], rnd, '11/27') for k in range(6)]
    blk = sorted(range(B0, B0 + BN), key=lambda i: (base[i][7], base[i][0])); assert blk != list(range(B0, B0 + BN))
    after = dict(adds); out = []; newline = {}; add_lines = []
    order = list(range(B0)) + blk + list(range(B0 + BN, 50000))
    for i in order:
        if i not in dele: out.append(fmt(new[i], i in v1)); newline[i] = len(out) + 1
        if i in after: out.append(fmt(after[i])); add_lines.append((len(out) + 1, after[i][0]))
    for r in tail: out.append(fmt(r)); add_lines.append((len(out) + 1, r[0]))
    old = [fmt(r) for r in base]
    assert len(out) == 50010 and sum(1 for i in c_qty + c_prc + c_loc + c_exp if fmt(new[i]) != old[i]) == 200 and all(fmt(new[i], i in v1) != old[i] for i in v1 + v2 + v3)
    assert set(out) - set(old) == {fmt(new[i], i in v1) for i in ex.keys() | set(v1 + v2 + v3)} | {fmt(r) for _, r in adds} | {fmt(r) for r in tail} and len(set(old) - set(out)) == 200 + 35 + 20
    text(f'{d}/在庫マスタ_2026年10月末.csv', ','.join(HDR) + '\n' + '\n'.join(old) + '\n', enc='shift_jis', eol='\r\n')
    text(f'{d}/在庫マスタ_2026年11月末.csv', ','.join(HDR) + '\n' + '\n'.join(out), enc='shift_jis', eol='\r\n')   # 最後の行に改行がない
    L = lambda i: f'{base[i][0]}（前月 {i + 2}行目→当月 {newline[i]}行目）'
    exs = lambda idx, n=4: '／'.join(f'{L(i)} {ex[i][1]}→{ex[i][2]}' for i in sorted(idx)[:n])
    nq = sum(1 for r in base if any(c in v for v in r for c in ',"'))

    # ---- 入出荷実績 TSV（UTF-8・BOM 付き・LF）。月初からの累計。27日分は26日分の行＋当日の行、途中に列が1つ増える
    r2 = random.Random(405); cust = [('C1001', '株式会社マルカワ商事'), ('C1002', '北星フーズ株式会社'), ('C1003', '有限会社いずみ屋'), ('C1004', 'サンルーフ物流株式会社 東京DC'), ('C1005', 'あおばドラッグ 本部'), ('C1006', '東雲ストア 物流センター'), ('C1007', 'ｷﾀﾉﾏｰﾄ（株）')]
    tanto = ['大谷', '神田', '須藤', '比嘉', '丸山']
    def rec(no, day):
        b = base[r2.randrange(50000)]; cu = r2.choice(cust); kb = r2.choice(['出荷', '出荷', '出荷', '入荷'])
        return [f'D2611{no:05d}', f'2026/11/{day:02d}', kb, cu[0], cu[1], b[0], str(r2.randrange(1, 240)), r2.choice(['CS', 'CS', 'PC', 'BL']), r2.choice(tanto), ('検品済' if kb == '入荷' else r2.choice(['出荷済', '出荷済', '出荷済', '出荷準備中']))]
    t26 = [rec(i + 1, 1 + i * 26 // 3900) for i in range(3900)]; t27n = [rec(3901 + i, 27) for i in range(260)]
    TH = ['伝票番号', '日付', '区分', '取引先コード', '取引先名', '商品コード', '数量', '単位', '担当', '状態']
    pend = [i for i, r in enumerate(t26) if r[9] == '出荷準備中']; st_chg = sorted(r2.sample(pend, 40)); sp4 = sorted(r2.sample([i for i in range(3900) if i not in st_chg], 8)); trail = sorted(r2.sample([i for i in range(3900) if i not in st_chg and i not in sp4], 12))
    def l27(i, r):
        r = list(r)
        if i in st_chg: r[9] = '出荷済'
        if i in trail: r[4] += '  '
        r = r[:6] + [('冷蔵' if r[5][:2] == 'FD' and int(r[5][3:]) % 9 == 0 else '常温')] + r[6:]
        return '\t'.join(r[:7]) + '\t' + r[7] + ('    ' if i in sp4 else '\t') + '\t'.join(r[8:])
    text(f'{d}/入出荷実績_11月累計_20261126時点.tsv', '\t'.join(TH) + '\n' + ''.join('\t'.join(r) + '\n' for r in t26), bom=True)
    text(f'{d}/入出荷実績_11月累計_20261127時点.tsv', '\t'.join(TH[:6] + ['温度帯'] + TH[6:]) + '\n' + ''.join(l27(i, r) + '\n' for i, r in enumerate(t26)) + ''.join(l27(-1, r) + '\n' for r in t27n), bom=True)

    # ---- 棚卸差異表（Excel）速報 → 確定
    r3 = random.Random(406); items = [base[i] for i in sorted(r3.sample(range(50000), 242))]; lots = {}; meisai = []
    for b in items:
        tot = int(b[5]) if int(b[5]) > 0 else 36; k = r3.choice([1, 2, 2, 3]); cut = sorted(r3.sample(range(1, tot), k - 1)) if tot > k else []; parts = [y - x for x, y in zip([0] + cut, cut + [tot])]
        for j, pq in enumerate(parts): meisai.append([b[0], b[8][:-2] + f'{(int(b[8][-2:]) + j) % 100:02d}', b[7], pq])
        lots[b[0]] = tot
    def tana(path, n_items, fix):
        its = items[:n_items]; ms = [m for m in meisai if m[0] in {b[0] for b in its}]; rr = random.Random(407)
        wb = xlsxwriter.Workbook(P(path)); ws = wb.add_worksheet('差異表'); w2 = wb.add_worksheet('在庫明細')
        h = wb.add_format({'bold': True, 'bg_color': '#FCE4D6', 'border': 1, 'align': 'center'}); c = wb.add_format({'border': 1}); n0 = wb.add_format({'border': 1, 'num_format': '#,##0'}); ng = wb.add_format({'border': 1, 'num_format': '#,##0;[Red]-#,##0'}); n2 = wb.add_format({'border': 1, 'num_format': '#,##0.00'}); dt = wb.add_format({'border': 1, 'num_format': 'yyyy/mm/dd'}); bd = wb.add_format({'bold': True, 'num_format': '#,##0;[Red]-#,##0', 'top': 6})
        ws.merge_range(0, 0, 0, 7, f'棚卸差異表　東京第2センター　2026年11月度（{"確定" if fix else "速報"}）', wb.add_format({'bold': True, 'size': 13})); ws.write(1, 0, '棚卸基準日'); ws.write_datetime(1, 1, datetime.datetime(2026, 11, 30), dt); ws.write(1, 3, '作成'); ws.write_datetime(1, 4, datetime.datetime(2026, 12, 4 if fix else 1), dt)
        ws.write_row(2, 0, ['商品コード', '品名', '棚番', '帳簿数', '実棚数', '差異', '単価', '差異金額', '担当者コード', '前回差異', '棚卸日', '備考'], h); ws.set_column(1, 1, 30); ws.set_column(0, 0, 12); ws.set_column(8, 9, None, None, {'hidden': True}); ws.set_column(10, 11, 12)
        info = {}
